  mesh: import('@iwsdk/core').Mesh;
  vel: Vector3;
  life: number;
  maxLife: number;
}

export interface TrailPoint {
  pos: Vector3;
  age: number;
}

export interface TrickShot {
  name: string;
  desc: string;
  pos: Vector3;
  requireSwish: boolean;
  requireBank?: boolean;
}

export interface DailyChallenge {
  seed: number;
  shots: { pos: Vector3; label: string }[];
  date: string;
  bestScore: number;
}

