      showPanel(titleEntity);
    });

    // Apply loaded settings
    if (!tutorialSeen) {
      showPanel(tutorialEntity);
    } else {
      showPanel(titleEntity);
    }
    audio.startAmbient();
    audio.startSynthwaveMusic();
    applyTheme(assets, THEMES[gs.themeIndex], world.scene.fog as Fog);
    applyBallSkin(assets, BALL_SKINS[gs.ballSkinIndex]);
    trail.setColor(BALL_SKINS[gs.ballSkinIndex].glowColor);
  }

  // ============================================================
  // INPUT — BROWSER
  // ============================================================

  let isCharging = false;
  let chargePower = 0;
  let aimX = 0;
  let mouseY = 0;

  container.addEventListener('mousedown', (e) => {
    if (gs.state !== 'playing' || ballState.inFlight) return;
    isCharging = true;
    chargePower = 0;
    aimX = 0;
    mouseY = e.clientY;
    powerEntity.object3D!.visible = true;
  });

  container.addEventListener('mousemove', (e) => {
    if (!isCharging) return;
    aimX = (e.clientX / window.innerWidth - 0.5) * 2;
    const dy = mouseY - e.clientY;
    chargePower = Math.min(1, Math.max(0, dy / 200));
    updatePowerBar(chargePower);
    // Charge hum feedback
    if (chargePower > 0.1 && Math.random() < 0.15) {
      audio.playChargeHum(chargePower);
    }
    // Show arc preview while charging
    if (chargePower > 0.1) {
      arcPreview.show(ballState.pos.clone(), chargePower, aimX);
    }
  });

  container.addEventListener('mouseup', () => {
    if (!isCharging) return;
    isCharging = false;
    powerEntity.object3D!.visible = false;
    arcPreview.hide();
    if (gs.state === 'playing' && !ballState.inFlight && chargePower > 0.05) {
      shootBall(chargePower, aimX);
    }
  });

  window.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      if (gs.state === 'playing') {
        gs.state = 'paused';
        gs.paused = true;
        showPanel(pauseEntity);
      } else if (gs.state === 'paused') {
        resumeGame();
      }
    }
    // Quick restart with R key during gameover
    if (e.key === 'r' || e.key === 'R') {
      if (gs.state === 'gameover') {
        startGame(gs.mode);
      }
    }
    // Quick menu with M key during gameover
    if (e.key === 'm' || e.key === 'M') {
      if (gs.state === 'gameover') {
        quitToMenu();
      }
    }
    // Number keys 1-7 for quick mode select from title
    if (gs.state === 'title' || gs.state === 'modeselect') {
      if (e.key === '1') startGame('freethrow');
      else if (e.key === '2') startGame('threepoint');
      else if (e.key === '3') startGame('arcade');
      else if (e.key === '4') { gs.mode = 'horse'; gs.state = 'difficulty'; showPanel(diffEntity); }
      else if (e.key === '5') startGame('trickshot');
      else if (e.key === '6') { updateDailyUI(); showPanel(dailyEntity); }
      else if (e.key === '7') startGame('practice');
    }
  });

  // ============================================================
  // INPUT — XR CONTROLLERS
  // ============================================================

  let xrCharging = false;
  let xrChargeStart = 0;

  // ============================================================
  // PHYSICS CALLBACKS
  // ============================================================

  const physicsCallbacks = {
    onBackboardHit: (pos: Vector3) => {
      audio.playBackboardHit();
      particles.spawn(pos, 5, 0x00aaff);
    },
    onRimHit: (pos: Vector3) => {
      audio.playRimHit();
      particles.spawn(pos, 3, 0xff4400);
    },
    onFloorBounce: () => {
      audio.playBounceFloor();
    },
    onPassThroughHoop: () => {
      const result = processMadeShot();
      handleShotComplete(result);
    },
    onSettled: () => {
      gs.streak = 0;
      handleShotComplete({ made: false, swish: false, bankShot: false, points: 0, distance: 0 });
    },
    onOutOfBounds: () => {
      gs.streak = 0;
      handleShotComplete({ made: false, swish: false, bankShot: false, points: 0, distance: 0 });
    },
  };

  // ============================================================
  // MAIN LOOP
  // ============================================================

  let lastTime = performance.now();
  let elapsedTime = 0;

  function update() {
    const now = performance.now();
    const dt = Math.min((now - lastTime) / 1000, 0.05);
    lastTime = now;
    elapsedTime += dt;

    if (!uiBound) tryBindUI();

    // Countdown
    if (gs.state === 'countdown') {
      gs.countdownTimer += dt;
      if (gs.countdownTimer >= 1) {
        gs.countdownTimer = 0;
        gs.countdownValue--;
        const cdDoc = countdownEntity.getValue(PanelDocument, 'document') as UIKitDocument | undefined;
        if (gs.countdownValue > 0) {
          setText(cdDoc, 'cd-num', `${gs.countdownValue}`);
          audio.playCountdownTick();
        } else {
          setText(cdDoc, 'cd-num', 'GO!');
          setText(cdDoc, 'cd-label', '');
          audio.playGameStart();
          setTimeout(() => {
            gs.state = 'playing';
            hideAllPanels();
            hudEntity.object3D!.visible = true;
            assets.ball.visible = true;
            assets.ballGlow.visible = true;
            updateHUD();
          }, 500);
        }
      }
    }

    // Toast timer
    if (toastTimer > 0) {
      toastTimer -= dt;
      if (toastTimer <= 0) toastEntity.object3D!.visible = false;
    }

    // Game logic
    if (gs.state === 'playing' && !gs.paused) {
      updateBallPhysics(ballState, dt, assets.ball, trailPoints, physicsCallbacks);

      // Arcade timer
      if (gs.mode === 'arcade' && !ballState.inFlight) {
        gs.arcadeTimeLeft -= dt;
        if (gs.arcadeTimeLeft <= 0) {
          gs.arcadeTimeLeft = 0;
          endGame();
        }
        updateHUD();
      }

      // Three-point timer
      if (gs.mode === 'threepoint') {
        gs.threePointTimeLeft -= dt;
        if (gs.threePointTimeLeft <= 0) {
          gs.threePointRack = 5;
          endGame();
        }
      }

      // XR input
      const rightGamepad = (world.input as any).xr?.gamepads?.right;
      if (rightGamepad) {
        const triggerDown = rightGamepad.getButtonDown?.(InputComponent.Trigger);
        const triggerPressed = rightGamepad.getButtonPressed?.(InputComponent.Trigger);
        const triggerUp = rightGamepad.getButtonUp?.(InputComponent.Trigger);

        if (triggerDown && !ballState.inFlight) {
          xrCharging = true;
          xrChargeStart = now;
          powerEntity.object3D!.visible = true;
        }

        if (xrCharging && triggerPressed) {
          const elapsed = (now - xrChargeStart) / 1000;
          chargePower = Math.min(1, elapsed / 1.5);
          updatePowerBar(chargePower);
          if (chargePower > 0.1) {
            arcPreview.show(ballState.pos.clone(), chargePower, 0);
          }
        }

        if (triggerUp && xrCharging) {
          xrCharging = false;
          powerEntity.object3D!.visible = false;
          arcPreview.hide();
          if (chargePower > 0.05) {
            shootBall(chargePower, 0);
          }
        }

        if (rightGamepad.getButtonDown?.(InputComponent.B_Button)) {
          if (gs.state === 'playing') {
            gs.state = 'paused';
            gs.paused = true;
            showPanel(pauseEntity);
          }
        }
      }
    }

    // Particles
    particles.update(dt);

    // Ball trail
    trail.update(trailPoints, dt);

    // ============================================================
    // Round 4 Effect Updates
    // ============================================================

    // Ball shadow follows ball position
    ballShadow.update(ballState.pos);

    // Rim glow indicator
    rimGlow.update(ballState.pos, ballState.inFlight);

    // Instant replay ghost trail
    if (ballState.inFlight) {
      replay.recordPoint(ballState.pos, elapsedTime);
    }
    replay.update(dt, lastMakePath);

    // Score popups float upward
    scorePopups.update(dt);

    // Confetti
    confetti.update(dt);

    // Wind system
    wind.update(dt);
    if (ballState.inFlight && wind.getDirectionLabel() !== '') {
      wind.applyToBall(ballState.vel, dt);
    }

    // Idle dribble animation
    if (gs.state === 'playing' && !ballState.inFlight) {
      const dribbleHit = idleDribble.update(dt, ballState.pos, ballState.inFlight, true);
      assets.ball.position.copy(ballState.pos);
      if (dribbleHit) audio.playDribble();
    }

    // Net animation
    if (netAnimating) {
      const netElapsed = elapsedTime - netAnimStart;
      const intensity = Math.max(0, 1 - netElapsed / 1.5);
      animateNet(assets.netGroup, elapsedTime, intensity);
      if (intensity <= 0) netAnimating = false;
    }

    // Environment animations
    updateEnvironmentAnimations(assets, elapsedTime, dt);

    requestAnimationFrame(update);
  }

  update();
}

main().catch(console.error);

// ============================================================
// BALL PHYSICS — arc trajectory, collisions, settling
// ============================================================

import {
  Vector3,
  Mesh,
  MeshBasicMaterial,
  SphereGeometry,
  AdditiveBlending,
  Group,
} from '@iwsdk/core';
import {
  GRAVITY, BALL_RADIUS, RIM_RADIUS, RIM_HEIGHT,
  BACKBOARD_WIDTH, BACKBOARD_HEIGHT,
  type TrailPoint,
} from './types';
import { AudioManager } from './audio';

export interface BallPhysicsState {
  pos: Vector3;
  vel: Vector3;
  inFlight: boolean;
  settled: boolean;
  shotProcessed: boolean;
  settleTimer: number;
  bounceCount: number;
}

export function createBallPhysicsState(): BallPhysicsState {
  return {
    pos: new Vector3(0, 1.2, 4.6),
    vel: new Vector3(0, 0, 0),
    inFlight: false,
    settled: false,
    shotProcessed: false,
    settleTimer: 0,
    bounceCount: 0,
  };
}

export interface PhysicsCallbacks {
  onBackboardHit: (pos: Vector3) => void;
  onRimHit: (pos: Vector3) => void;
  onFloorBounce: () => void;
  onPassThroughHoop: () => void;
  onSettled: () => void;
  onOutOfBounds: () => void;
}

/**
 * Run one frame of ball physics with 4-substep integration.
 * Returns true if the ball is still in flight.
 */
export function updateBallPhysics(
  state: BallPhysicsState,
  dt: number,
  ball: Mesh,
  trailPoints: TrailPoint[],
  callbacks: PhysicsCallbacks,
): boolean {
  if (!state.inFlight) return false;

  const substeps = 4;
  const subDt = dt / substeps;

  for (let s = 0; s < substeps; s++) {
    // Gravity
    state.vel.y += GRAVITY * subDt;

    // Position
    state.pos.x += state.vel.x * subDt;
    state.pos.y += state.vel.y * subDt;
    state.pos.z += state.vel.z * subDt;

    // Floor bounce
    if (state.pos.y < BALL_RADIUS) {
      state.pos.y = BALL_RADIUS;
      state.vel.y *= -0.6;
      state.vel.x *= 0.8;
      state.vel.z *= 0.8;
      if (Math.abs(state.vel.y) > 0.3) {
        callbacks.onFloorBounce();
      }
    }

    // Backboard collision
    if (state.pos.z < -0.13 && state.pos.z > -0.2 &&
        Math.abs(state.pos.x) < BACKBOARD_WIDTH / 2 &&
        state.pos.y > RIM_HEIGHT - 0.1 && state.pos.y < RIM_HEIGHT + BACKBOARD_HEIGHT) {
      state.pos.z = -0.13;
      state.vel.z *= -0.65;
      state.bounceCount++;
      callbacks.onBackboardHit(state.pos.clone());
    }

    // Rim collision
    const dx = state.pos.x;
    const dz = state.pos.z;
    const rimDist = Math.sqrt(dx * dx + dz * dz);
    const rimDiff = Math.abs(rimDist - RIM_RADIUS);

    if (rimDiff < BALL_RADIUS + 0.02 && Math.abs(state.pos.y - RIM_HEIGHT) < BALL_RADIUS + 0.05) {
      const nx = dx / (rimDist || 1);
      const nz = dz / (rimDist || 1);
      const dot = state.vel.x * nx + state.vel.z * nz;
      state.vel.x -= 1.5 * dot * nx;
      state.vel.z -= 1.5 * dot * nz;
      state.vel.y *= 0.7;

      if (rimDist < RIM_RADIUS) {
        state.pos.x = nx * (RIM_RADIUS - BALL_RADIUS - 0.03);
        state.pos.z = nz * (RIM_RADIUS - BALL_RADIUS - 0.03);
      } else {
        state.pos.x = nx * (RIM_RADIUS + BALL_RADIUS + 0.03);
        state.pos.z = nz * (RIM_RADIUS + BALL_RADIUS + 0.03);
      }

      state.bounceCount++;
      callbacks.onRimHit(state.pos.clone());
    }

    // Pass through hoop
    if (!state.shotProcessed && state.pos.y < RIM_HEIGHT && state.pos.y > RIM_HEIGHT - 0.5) {
      const passThrough = Math.sqrt(state.pos.x * state.pos.x + state.pos.z * state.pos.z) < RIM_RADIUS - BALL_RADIUS * 0.5;
      if (passThrough && state.vel.y < 0) {
        state.shotProcessed = true;
        callbacks.onPassThroughHoop();
        return true;
      }
    }
  }

  // Ball rotation
  const speed = state.vel.length();
  if (speed > 0.1) {
    ball.rotation.x += state.vel.z * dt * 3;
    ball.rotation.z -= state.vel.x * dt * 3;
  }

  ball.position.copy(state.pos);

  // Trail
  if (speed > 1) {
    trailPoints.push({ pos: state.pos.clone(), age: 0 });
    if (trailPoints.length > 30) trailPoints.shift();
  }

  // Settled (miss)
  if (state.pos.y < BALL_RADIUS + 0.1 && speed < 0.3) {
    state.settleTimer += dt;
    if (state.settleTimer > 1.0 && !state.shotProcessed) {
      state.shotProcessed = true;
      callbacks.onSettled();
    }
  }

  // Out of bounds
  if (state.pos.y < -2 || Math.abs(state.pos.x) > 15 || Math.abs(state.pos.z) > 20) {
    if (!state.shotProcessed) {
      state.shotProcessed = true;
      callbacks.onOutOfBounds();
    }
  }

  return true;
}

/**
 * Launch the ball toward the hoop with given power and aim offset.
 */
export function launchBall(
  state: BallPhysicsState,
  power: number,
  aimAngle: number,
): void {
  state.inFlight = true;
  state.shotProcessed = false;
  state.settleTimer = 0;
  state.bounceCount = 0;

  const toHoop = new Vector3(0, RIM_HEIGHT, 0).sub(state.pos);
  const dist = Math.sqrt(toHoop.x * toHoop.x + toHoop.z * toHoop.z);
  const arcAngle = 0.8 + (1 - power) * 0.4;
  const speed = 5 + power * 7 + dist * 0.5;
  const horizDir = new Vector3(toHoop.x, 0, toHoop.z).normalize();
  horizDir.x += aimAngle * 0.3;
  horizDir.normalize();

  state.vel.set(
    horizDir.x * speed * Math.cos(arcAngle),
    speed * Math.sin(arcAngle),
    horizDir.z * speed * Math.cos(arcAngle),
  );
}

// ============================================================
// TRAIL RENDERER
// ============================================================

export class TrailRenderer {
  private segments: Mesh[] = [];
  private scene: Group;
  private maxSegments = 20;

  constructor(scene: Group) {
    this.scene = scene;
    for (let i = 0; i < this.maxSegments; i++) {
      const mesh = new Mesh(
        new SphereGeometry(0.03 + (1 - i / this.maxSegments) * 0.04, 4, 4),
        new MeshBasicMaterial({
          color: 0xff6600,
          transparent: true,
          opacity: 0,
          blending: AdditiveBlending,
        }),
      );
      mesh.visible = false;
      scene.add(mesh);
      this.segments.push(mesh);
    }
  }

  update(trailPoints: TrailPoint[], dt: number) {
    // Age and remove old points
    for (let i = trailPoints.length - 1; i >= 0; i--) {
      trailPoints[i].age += dt;
      if (trailPoints[i].age > 0.5) trailPoints.splice(i, 1);
    }

    // Update visual segments
    for (let i = 0; i < this.maxSegments; i++) {
      const seg = this.segments[i];
      if (i < trailPoints.length) {
        const pt = trailPoints[trailPoints.length - 1 - i];
        seg.position.copy(pt.pos);
        const alpha = 1 - pt.age / 0.5;
        (seg.material as MeshBasicMaterial).opacity = alpha * 0.4;
        seg.scale.setScalar(alpha * 0.8);
        seg.visible = true;
      } else {
        seg.visible = false;
      }
    }
  }

  setColor(color: number) {
    this.segments.forEach(s => {
      (s.material as MeshBasicMaterial).color.setHex(color);
    });
  }
}

// ============================================================
// SHOT ARC PREVIEW
// ============================================================

export class ArcPreview {
  private dots: Mesh[] = [];
  private scene: Group;
  private dotCount = 15;

  constructor(scene: Group) {
    this.scene = scene;
    const mat = new MeshBasicMaterial({
      color: 0xffffff,
      transparent: true,
      opacity: 0.3,
      blending: AdditiveBlending,
    });
    for (let i = 0; i < this.dotCount; i++) {
      const dot = new Mesh(new SphereGeometry(0.015, 4, 4), mat.clone());
      dot.visible = false;
      scene.add(dot);
      this.dots.push(dot);
    }
  }

  show(startPos: Vector3, power: number, aimAngle: number) {
    const vel = new Vector3();
    const toHoop = new Vector3(0, RIM_HEIGHT, 0).sub(startPos);
    const dist = Math.sqrt(toHoop.x * toHoop.x + toHoop.z * toHoop.z);
    const arcAngle = 0.8 + (1 - power) * 0.4;
    const speed = 5 + power * 7 + dist * 0.5;
    const horizDir = new Vector3(toHoop.x, 0, toHoop.z).normalize();
    horizDir.x += aimAngle * 0.3;
    horizDir.normalize();
    vel.set(
      horizDir.x * speed * Math.cos(arcAngle),
      speed * Math.sin(arcAngle),
      horizDir.z * speed * Math.cos(arcAngle),
    );

    const pos = startPos.clone();
    const timeStep = 0.08;
    for (let i = 0; i < this.dotCount; i++) {
      pos.x += vel.x * timeStep;
      pos.y += vel.y * timeStep;
      pos.z += vel.z * timeStep;
      vel.y += GRAVITY * timeStep;

      this.dots[i].position.copy(pos);
      const alpha = 0.5 * (1 - i / this.dotCount);
      (this.dots[i].material as MeshBasicMaterial).opacity = alpha;
      this.dots[i].visible = true;
    }
  }

  hide() {
    this.dots.forEach(d => { d.visible = false; });
  }
}

// ============================================================
// EFFECTS — ball shadow, rim glow, replay ghost, score popups,
//           confetti, wind, idle dribble
// ============================================================

import {
  Mesh,
  MeshBasicMaterial,
  MeshStandardMaterial,
  SphereGeometry,
  PlaneGeometry,
  CircleGeometry,
  Vector3,
  Group,
  Color,
  AdditiveBlending,
} from '@iwsdk/core';
import { BALL_RADIUS, RIM_HEIGHT, RIM_RADIUS, GRAVITY } from './types';

// ============================================================
// BALL SHADOW
// ============================================================

export class BallShadow {
  private shadow: Mesh;
  private mat: MeshBasicMaterial;

  constructor(scene: Group) {
    this.mat = new MeshBasicMaterial({
      color: 0x000000,
      transparent: true,
      opacity: 0.25,
    });
    this.shadow = new Mesh(new CircleGeometry(BALL_RADIUS * 1.2, 16), this.mat);
    this.shadow.rotation.x = -Math.PI / 2;
    this.shadow.position.y = 0.005;
    scene.add(this.shadow);
  }

  update(ballPos: Vector3) {
    this.shadow.position.x = ballPos.x;
    this.shadow.position.z = ballPos.z;
    // Scale & opacity based on height — higher ball = smaller/lighter shadow
    const heightFactor = Math.max(0, 1 - ballPos.y / 8);
    const scale = 0.5 + heightFactor * 0.8;
    this.shadow.scale.setScalar(scale);
    this.mat.opacity = 0.15 * heightFactor;
    this.shadow.visible = ballPos.y > 0.1;
  }
}

// ============================================================
// RIM GLOW INDICATOR — color shifts based on ball proximity
// ============================================================

export class RimGlowIndicator {
  private glowRing: Mesh;
  private mat: MeshBasicMaterial;

  constructor(scene: Group) {
    this.mat = new MeshBasicMaterial({
      color: 0x00ff00,
      transparent: true,
      opacity: 0,
      blending: AdditiveBlending,
    });
    // Flat ring at hoop height
    const geo = new PlaneGeometry(RIM_RADIUS * 3.2, RIM_RADIUS * 3.2);
    this.glowRing = new Mesh(geo, this.mat);
    this.glowRing.rotation.x = -Math.PI / 2;
    this.glowRing.position.set(0, RIM_HEIGHT + 0.01, 0);
    this.glowRing.visible = false;
    scene.add(this.glowRing);
  }

  update(ballPos: Vector3, ballInFlight: boolean) {
    if (!ballInFlight) {
      this.glowRing.visible = false;
      return;
    }

    // Only show when ball is near hoop height and within range
    const dy = Math.abs(ballPos.y - RIM_HEIGHT);
    const horiz = Math.sqrt(ballPos.x * ballPos.x + ballPos.z * ballPos.z);

    if (dy < 1.5 && horiz < RIM_RADIUS * 4) {
      this.glowRing.visible = true;
      // Distance from center of hoop — green=perfect, yellow=close, red=miss
      const centerDist = horiz / RIM_RADIUS;
      if (centerDist < 0.6) {
        this.mat.color.setHex(0x00ff44); // Dead center — green
      } else if (centerDist < 1.0) {
        this.mat.color.setHex(0xffff00); // Close — yellow
      } else if (centerDist < 1.5) {
        this.mat.color.setHex(0xff8800); // Rim area — orange
      } else {
        this.mat.color.setHex(0xff0000); // Missing — red
      }
      // Fade based on vertical proximity
      this.mat.opacity = Math.max(0, 0.12 * (1 - dy / 1.5));
    } else {
      this.glowRing.visible = false;
    }
  }
}

// ============================================================
// INSTANT REPLAY — ghost trail of last successful shot
// ============================================================

export interface ReplayPoint {
  pos: Vector3;
  time: number;
}

export class InstantReplay {
  private ghostDots: Mesh[] = [];
  private scene: Group;
  private savedPath: ReplayPoint[] = [];
  private active = false;
  private replayTime = 0;
  private maxDots = 25;

  constructor(scene: Group) {
    this.scene = scene;
    const mat = new MeshBasicMaterial({
      color: 0x44ddff,
      transparent: true,
      opacity: 0,
      blending: AdditiveBlending,
    });
    for (let i = 0; i < this.maxDots; i++) {
      const dot = new Mesh(new SphereGeometry(0.025, 4, 4), mat.clone());
      dot.visible = false;
      scene.add(dot);
      this.ghostDots.push(dot);
    }
  }

  /** Record the current ball position during flight */
  recordPoint(pos: Vector3, time: number) {
    this.savedPath.push({ pos: pos.clone(), time });
    if (this.savedPath.length > 200) this.savedPath.shift();
  }

  /** Start replay after a successful make */
  startReplay() {
    if (this.savedPath.length < 5) return;
    this.active = true;
    this.replayTime = 0;
  }

  /** Save current path as the "last shot" and clear recording buffer */
  commitPath(): ReplayPoint[] {
    const path = [...this.savedPath];
    this.savedPath = [];
    return path;
  }

  /** Clear the recording buffer without saving */
  clearRecording() {
    this.savedPath = [];
  }

  update(dt: number, lastMakePath: ReplayPoint[]) {
    if (!this.active || lastMakePath.length === 0) {
      this.ghostDots.forEach(d => { d.visible = false; });
      return;
    }

    this.replayTime += dt;
    const totalDuration = lastMakePath[lastMakePath.length - 1].time - lastMakePath[0].time;

    if (this.replayTime > totalDuration + 1.0) {
      // Replay finished
      this.active = false;
      this.ghostDots.forEach(d => { d.visible = false; });
      return;
    }

    // Show dots along the path up to current replay time
    const startTime = lastMakePath[0].time;
    const fadeWindow = 0.8;

    for (let i = 0; i < this.maxDots; i++) {
      const t = (i / this.maxDots) * totalDuration;
      if (t > this.replayTime) {
        this.ghostDots[i].visible = false;
        continue;
      }

      // Find closest recorded point
      const targetTime = startTime + t;
      let closest = lastMakePath[0];
      for (const p of lastMakePath) {
        if (Math.abs(p.time - targetTime) < Math.abs(closest.time - targetTime)) {
          closest = p;
        }
      }

      this.ghostDots[i].position.copy(closest.pos);
      this.ghostDots[i].visible = true;

      // Fade: newest dots brighter, old dots fade
      const age = this.replayTime - t;
      const alpha = Math.max(0, 0.5 * (1 - age / fadeWindow));
      (this.ghostDots[i].material as MeshBasicMaterial).opacity = alpha;
      this.ghostDots[i].scale.setScalar(0.5 + alpha);
    }
  }
}

// ============================================================
// SCORE POPUP — floating "+N" text effect using PanelUI-safe mesh
// ============================================================

export interface ScorePopup {
  mesh: Mesh;
  vel: Vector3;
  life: number;
  maxLife: number;
}

export class ScorePopupSystem {
  private popups: ScorePopup[] = [];
  private scene: Group;

  constructor(scene: Group) {
    this.scene = scene;
  }

  spawn(pos: Vector3, color: number) {
    const mat = new MeshBasicMaterial({
      color,
      transparent: true,
      opacity: 0.9,
      blending: AdditiveBlending,
    });
    // Use a small star-like shape instead of text (PanelUI handles text, this is a visual accent)
    const mesh = new Mesh(new SphereGeometry(0.04, 6, 6), mat);
    mesh.position.copy(pos);
    mesh.position.y += 0.5;
    this.scene.add(mesh);

    this.popups.push({
      mesh,
      vel: new Vector3((Math.random() - 0.5) * 0.5, 2.5, (Math.random() - 0.5) * 0.5),
      life: 0,
      maxLife: 1.5,
    });
  }

  update(dt: number) {
    for (let i = this.popups.length - 1; i >= 0; i--) {
      const p = this.popups[i];
      p.life += dt;
      p.mesh.position.add(p.vel.clone().multiplyScalar(dt));
      p.vel.y -= 1.5 * dt; // Slow gravity
      const alpha = 1 - p.life / p.maxLife;
      (p.mesh.material as MeshBasicMaterial).opacity = alpha * 0.9;
      p.mesh.scale.setScalar(1 + p.life * 0.5); // Grow as they rise

      if (p.life >= p.maxLife) {
        this.scene.remove(p.mesh);
        this.popups.splice(i, 1);
      }
    }
  }

  clear() {
    this.popups.forEach(p => this.scene.remove(p.mesh));
    this.popups.length = 0;
  }
}

// ============================================================
// CONFETTI BURST — for achievements & big moments
// ============================================================

export interface ConfettiPiece {
  mesh: Mesh;
  vel: Vector3;
  rotVel: Vector3;
  life: number;
  maxLife: number;
}

export class ConfettiSystem {
  private pieces: ConfettiPiece[] = [];
  private scene: Group;
  private maxPieces = 60;

  constructor(scene: Group) {
    this.scene = scene;
  }

  burst(pos: Vector3, count: number = 30) {
    const colors = [0xff0044, 0xff8800, 0xffff00, 0x00ff44, 0x00aaff, 0xff00ff, 0xffffff];
    for (let i = 0; i < count && this.pieces.length < this.maxPieces; i++) {
      const color = colors[Math.floor(Math.random() * colors.length)];
      const mat = new MeshBasicMaterial({ color, transparent: true, opacity: 0.9 });
      // Flat confetti rectangle
      const w = 0.015 + Math.random() * 0.02;
      const h = 0.03 + Math.random() * 0.04;
      const mesh = new Mesh(new PlaneGeometry(w, h), mat);
      mesh.position.copy(pos);
      this.scene.add(mesh);

      this.pieces.push({
        mesh,
        vel: new Vector3(
          (Math.random() - 0.5) * 6,
          Math.random() * 5 + 3,
          (Math.random() - 0.5) * 6,
        ),
        rotVel: new Vector3(
          (Math.random() - 0.5) * 10,
          (Math.random() - 0.5) * 10,
          (Math.random() - 0.5) * 10,
        ),
        life: 0,
        maxLife: 2.0 + Math.random() * 1.0,
      });
    }
  }

  update(dt: number) {
    for (let i = this.pieces.length - 1; i >= 0; i--) {
      const p = this.pieces[i];
      p.life += dt;
      p.vel.y += GRAVITY * 0.3 * dt; // Slow-falling confetti
      // Flutter effect
      p.vel.x += Math.sin(p.life * 5 + i) * 0.5 * dt;
      p.vel.z += Math.cos(p.life * 4 + i) * 0.5 * dt;
      p.mesh.position.add(p.vel.clone().multiplyScalar(dt));
      p.mesh.rotation.x += p.rotVel.x * dt;
      p.mesh.rotation.y += p.rotVel.y * dt;
      p.mesh.rotation.z += p.rotVel.z * dt;

      const alpha = 1 - p.life / p.maxLife;
      (p.mesh.material as MeshBasicMaterial).opacity = alpha * 0.9;

      if (p.life >= p.maxLife || p.mesh.position.y < -1) {
        this.scene.remove(p.mesh);
        this.pieces.splice(i, 1);
      }
    }
  }

  clear() {
    this.pieces.forEach(p => this.scene.remove(p.mesh));
    this.pieces.length = 0;
  }
}

// ============================================================
// WIND SYSTEM — affects ball trajectory based on difficulty
// ============================================================

export class WindSystem {
  windX = 0;
  windZ = 0;
  private strength = 0;
  private changeTimer = 0;
  private targetX = 0;
  private targetZ = 0;

  setDifficulty(level: 'easy' | 'medium' | 'hard') {
    switch (level) {
      case 'easy': this.strength = 0; break;
      case 'medium': this.strength = 0.8; break;
      case 'hard': this.strength = 2.0; break;
    }
  }

  update(dt: number) {
    this.changeTimer += dt;
    if (this.changeTimer > 3.0) {
      this.changeTimer = 0;
      this.targetX = (Math.random() - 0.5) * 2 * this.strength;
      this.targetZ = (Math.random() - 0.5) * 2 * this.strength;
    }
    // Smooth lerp toward target
    this.windX += (this.targetX - this.windX) * dt * 0.5;
    this.windZ += (this.targetZ - this.windZ) * dt * 0.5;
  }

  /** Apply wind force to ball velocity */
  applyToBall(vel: Vector3, dt: number) {
    vel.x += this.windX * dt;
    vel.z += this.windZ * dt;
  }

  getDirectionLabel(): string {
    if (this.strength === 0) return '';
    const mag = Math.sqrt(this.windX * this.windX + this.windZ * this.windZ);
    if (mag < 0.2) return 'CALM';
    let dir = '';
    if (this.windZ < -0.2) dir += 'N';
    if (this.windZ > 0.2) dir += 'S';
    if (this.windX < -0.2) dir += 'W';
    if (this.windX > 0.2) dir += 'E';
    return `WIND: ${dir} ${mag.toFixed(1)}`;
  }
}

// ============================================================
// IDLE BALL DRIBBLE ANIMATION
// ============================================================

export class IdleDribble {
  private timer = 0;
  private bouncing = false;
  private bouncePhase = 0;
  private baseY = 1.2;

  update(dt: number, ballPos: Vector3, inFlight: boolean, isPlaying: boolean): boolean {
    if (inFlight || !isPlaying) {
      this.timer = 0;
      this.bouncing = false;
      return false;
    }

    this.timer += dt;

    // Start idle dribble after 3 seconds of inactivity
    if (this.timer < 3.0 && !this.bouncing) return false;

    this.bouncing = true;
    this.bouncePhase += dt * 4; // Dribble speed

    // Smooth bounce curve
    const bounce = Math.abs(Math.sin(this.bouncePhase)) * 0.25;
    ballPos.y = this.baseY + bounce;

    // Return true when ball hits bottom of bounce (for dribble sound)
    const prevBounce = Math.abs(Math.sin(this.bouncePhase - dt * 4));
    return bounce < 0.02 && prevBounce > 0.02;
  }

  reset() {
    this.timer = 0;
    this.bouncing = false;
    this.bouncePhase = 0;
  }
}

