  stopSynthwaveMusic() {
    this.musicPlaying = false;
    if (this.musicLoopTimer) {
      clearInterval(this.musicLoopTimer);
      this.musicLoopTimer = null;
    }
    this.musicNodes.forEach(n => { try { n.stop(); } catch {} });
    this.musicNodes = [];
  }
}

